VALUES ('Anou Araren Coal Mine', 'Societe Nigerienne de Charbon (SONICHAR)', NULL, NULL, NULL, 'Niger', 'Agadez Region', 'Anou Araren, near Tchirozerine town, Agadez Region, Niger', 18.53, 8.73, 'No direct port access — landlocked; coal consumed on-site at power plant', 'No railway — road transport only', 1975, 44, 'Government of Niger', '[{"year": 1975, "event": "SONICHAR created by Government of Niger to mine coal and operate associated power plant"}, {"year": 1980, "event": "Coal mining operations commenced at Anou Araren open-pit mine"}, {"year": 1981, "event": "Associated thermal power plant commissioned — 37.7 MW capacity"}]'::jsonb, '[{"year": null, "event": "Only commercial coal mine in Niger"}, {"year": null, "event": "Coal used exclusively for 37.7 MW thermal power station serving Agadez and uranium mines at Arlit"}, {"year": 2011, "event": "Production: 246,016 tonnes (86% used by adjacent power plant)"}, {"year": null, "event": "Proved reserves: 6-15 million tonnes"}, {"year": null, "event": "Second deposit at Salkadamna (Tahoua): 70-92 Mt; development begun 2014"}]'::jsonb, '[]'::jsonb, NULL, 'Sub-bituminous / lignitic', 'Anou Araren coalfield — Agadez', NULL, NULL, NULL, NULL, NULL, 246000, NULL, 'Open cast / strip mining', NULL, NULL, NULL, NULL, NULL, 'On-site power plant only — no export', '["Conveyor / short haul road — power plant ~2km from mine"]'::jsonb, NULL, false, '[]'::jsonb)
